import React from 'react';
import PromotionItem from './PromotionItem';
import '../styles/PromotionSection.css';

const PromotionSection = () => {
    const products = [
        { 
            id: 1, 
            title: 'Крісло GASPAR', 
            img: `${process.env.PUBLIC_URL}/imgg/Frame 12.png`, 
            rating: 5.0, 
            price: 6999, 
            oldPrice: 9999, 
            discount: 30 
        },
        { 
            id: 2, 
            title: 'Стіл дерев\'яний', 
            img: `${process.env.PUBLIC_URL}/imgg/Frame 11.png`, 
            rating: 4.5, 
            price: 4590 
        },
        { 
            id: 3, 
            title: 'Диван сірий', 
            img: `${process.env.PUBLIC_URL}/imgg/Frame 14.png`, 
            rating: 4.8, 
            price: 12999, 
            oldPrice: 15999, 
            discount: 19 
        },
        { 
            id: 4, 
            title: 'Лампа настільна', 
            img: `${process.env.PUBLIC_URL}/imgg/Frame 10.png`, 
            rating: 3.7, 
            price: 890 
        }
    ];

    return (
        <section className="promotion-section">
            <div className="promotion-left">
                <img src={`${process.env.PUBLIC_URL}/imgg/Group 518.png`} alt="Акційна пропозиція" />
            </div>
            <div className="promotion-right">
                <div className="promotion-items">
                    {products.map(product => (
                        <PromotionItem key={product.id} item={product} />
                    ))}
                </div>
            </div>
        </section>
    );
};

export default PromotionSection;
